/* ---------- Category image URLs from LinkList item text ---------- */
$$('.cat').forEach(function(card){
  var raw=$('.cat-name',card),visual=$('.cat-ico',card);if(!raw||!visual)return;
  var value=(raw.textContent||'').trim(),parts=value.split('|'),url=parts.length>1?parts.slice(1).join('|').trim():'';
  if(url&&/^https?:\/\//i.test(url)){
    var label=parts[0].trim(),im=d.createElement('img');im.src=url;im.alt=label;im.loading='lazy';
    visual.textContent='';visual.appendChild(im);raw.textContent=label;card.classList.add('has-category-image');
  }
