/* ---------- E-commerce style image gallery for multi-image posts ---------- */
$$('.post-body').forEach(function(content){
  if(content.closest('.post-gallery'))return;
  var imgs=$$('img',content).filter(function(im){return im.src&&!im.closest('a[data-fancybox="gallery-disabled"]')&&!im.classList.contains('emoji')});
  if(imgs.length<2)return;
  var gallery=d.createElement('div');gallery.className='post-gallery';gallery.setAttribute('aria-label','Product image gallery');
  var main=d.createElement('div');main.className='post-gallery-main';
  var thumbs=d.createElement('div');thumbs.className='post-gallery-thumbs';
  var navPrev=d.createElement('button'),navNext=d.createElement('button'),count=d.createElement('span');
  navPrev.type=navNext.type='button';navPrev.className='post-gallery-nav prev';navNext.className='post-gallery-nav next';navPrev.innerHTML='&#8249;';navNext.innerHTML='&#8250;';navPrev.setAttribute('aria-label','Previous image');navNext.setAttribute('aria-label','Next image');
  count.className='post-gallery-count';
  var slides=[];imgs.forEach(function(original,index){
    var src=original.getAttribute('data-src')||original.src;
    var slide=d.createElement('img');slide.src=src;slide.alt=original.alt||('Product image '+(index+1));slide.loading=index===0?'eager':'lazy';if(index===0)slide.className='active';main.appendChild(slide);slides.push(slide);
    var thumb=d.createElement('button');thumb.type='button';thumb.className=index===0?'active':'';thumb.setAttribute('aria-label','Show image '+(index+1));var ti=d.createElement('img');ti.src=src;ti.alt='';ti.loading='lazy';thumb.appendChild(ti);thumb.addEventListener('click',function(){showSlide(index)});thumbs.appendChild(thumb);
  });
  var active=0;function showSlide(index){active=(index+slides.length)%slides.length;slides.forEach(function(im,i){im.classList.toggle('active',i===active)});$$('button',thumbs).forEach(function(b,i){b.classList.toggle('active',i===active)});count.textContent=(active+1)+' / '+slides.length}
  navPrev.addEventListener('click',function(){showSlide(active-1)});navNext.addEventListener('click',function(){showSlide(active+1)});
  main.appendChild(navPrev);main.appendChild(navNext);main.appendChild(count);gallery.appendChild(main);gallery.appendChild(thumbs);
  var first=imgs[0],host=first.closest('.separator')||first.parentNode;
  content.insertBefore(gallery,content.firstChild);
  imgs.forEach(function(im){var sep=im.closest('.separator');if(sep&&sep.parentNode)sep.parentNode.removeChild(sep);else if(im.parentNode)im.parentNode.removeChild(im)});
  showSlide(0);
});

/* ---------- Review star selector (Blogger remains the comment backend) ---------- */
$$('.review-rating').forEach(function(widget){
  var value=0,stars=$$('button[data-rating]',widget),out=$('.review-rating-value',widget),hint=$('.review-rating-hint',widget);
  stars.forEach(function(star){star.addEventListener('click',function(){value=parseInt(star.getAttribute('data-rating'),10)||0;stars.forEach(function(item){item.classList.toggle('active',(parseInt(item.getAttribute('data-rating'),10)||0)<=value);item.setAttribute('aria-pressed',(parseInt(item.getAttribute('data-rating'),10)||0)===value?'true':'false')});if(out)out.textContent=value+' / 5 stars';if(hint)hint.textContent='Rating selected. Please include this rating in your review text so it is saved with your Blogger comment.'})});
});

